  function formatLift(L){
    L = String(L || "").trim();
    if(!L) return "";
    return /^Снять\s*:/i.test(L) ? L : ("Снять: " + L);
  }
  function formatLiftLabel(L){
    return /^Снять\s*:/i.test(String(L || "").trim()) ? "" : DATA.verdictBlocks[2];
  }
  function resolvePunch(punch, powerId){
    if(punch == null) return "";
    if(typeof punch === "string") return punch;
    return punch[powerId] || punch.seal || punch.whisper || punch.anathema || "";
  }

