  /* ---------- share poster (1080×1920, Meta Stories safe band) ---------- */
  function wrapText(ctx, text, maxW){
    const words = String(text || "").split(/\s+/);
    const lines = [];
    let line = "";
    for(let i=0;i<words.length;i++){
      const test = line ? line + " " + words[i] : words[i];
      if(ctx.measureText(test).width > maxW && line){
        lines.push(line);
        line = words[i];
      } else line = test;
    }
    if(line) lines.push(line);
    return lines;
  }
  function drawRoundedRect(ctx, x, y, w, h, r){
    const rr = Math.min(r, w/2, h/2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }
  function addGrain(ctx, x, y, w, h, dens){
    const n = dens || 1800;
    ctx.save();
    for(let i=0;i<n;i++){
      const gx = x + Math.random() * w;
      const gy = y + Math.random() * h;
      const a = 0.02 + Math.random() * 0.06;
      ctx.fillStyle = Math.random() > .5 ? "rgba(255,255,255," + a + ")" : "rgba(0,0,0," + a + ")";
      ctx.fillRect(gx, gy, 1.5, 1.5);
    }
    ctx.restore();
  }
  function setSpacing(ctx, px){
    try{ if("letterSpacing" in ctx) ctx.letterSpacing = px + "px"; }catch(e){}
  }
  function powerColorOf(pid){
    return pid === "anathema" ? "#FF3B2F" : pid === "whisper" ? "#C98A84" : "#E5262F";
  }
  function drawCrown(ctx, cx, cy, w, color){
    const h = w * 0.72;
    ctx.save();
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx - w/2, cy + h*0.45);
    ctx.lineTo(cx - w*0.36, cy - h*0.2);
    ctx.lineTo(cx - w*0.16, cy + h*0.05);
    ctx.lineTo(cx, cy - h*0.5);
    ctx.lineTo(cx + w*0.16, cy + h*0.05);
    ctx.lineTo(cx + w*0.36, cy - h*0.2);
    ctx.lineTo(cx + w/2, cy + h*0.45);
    ctx.closePath();
    ctx.fill();
    ctx.fillRect(cx - w/2, cy + h*0.5, w, Math.max(2, h*0.14));
    ctx.restore();
  }
  // Occult sigil: glowing concentric rune rings + gold crown (poster art)
  function drawSigil(ctx, cx, cy, r, color, glow){
    ctx.save();
    const grd = ctx.createRadialGradient(cx, cy, 0, cx, cy, r * 1.1);
    grd.addColorStop(0, "rgba(179,18,31," + (0.22 * glow) + ")");
    grd.addColorStop(1, "rgba(179,18,31,0)");
    ctx.fillStyle = grd;
    ctx.beginPath();
    ctx.ellipse(cx, cy, r * 1.1, r * 0.5, 0, 0, Math.PI * 2);
    ctx.fill();
    const stone = ctx.createLinearGradient(cx, cy - r*0.42, cx, cy + r*0.42);
    stone.addColorStop(0, "#241D1A");
    stone.addColorStop(1, "#0E0B0A");
    ctx.fillStyle = stone;
    ctx.beginPath();
    ctx.ellipse(cx, cy, r, r * 0.42, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowColor = color;
    ctx.shadowBlur = 26 * glow;
    for(let i=0;i<3;i++){
      const k = 1 - i * 0.24;
      ctx.beginPath();
      ctx.ellipse(cx, cy, r * 0.9 * k, r * 0.42 * 0.9 * k, 0, 0, Math.PI * 2);
      ctx.strokeStyle = color;
      ctx.globalAlpha = 0.9 - i * 0.2;
      ctx.lineWidth = i === 0 ? 3 : 2;
      ctx.stroke();
    }
    ctx.globalAlpha = .7;
    ctx.lineWidth = 2;
    for(let k=0;k<40;k++){
      const a = k / 40 * Math.PI * 2;
      const rx1 = r * 0.9, ry1 = r * 0.42 * 0.9, rx2 = r * 0.8, ry2 = r * 0.42 * 0.8;
      ctx.beginPath();
      ctx.moveTo(cx + Math.cos(a) * rx1, cy + Math.sin(a) * ry1);
      ctx.lineTo(cx + Math.cos(a) * rx2, cy + Math.sin(a) * ry2);
      ctx.stroke();
    }
    ctx.shadowBlur = 0;
    ctx.globalAlpha = 1;
    drawCrown(ctx, cx, cy - r * 0.08, r * 0.34, "#C9A24A");
    ctx.restore();
  }

  function shortPunch(punch, maxLen){
    const lim = (maxLen == null) ? 280 : maxLen;
    const t = String(punch || "").replace(/^А\s+/i, "").trim();
    if(t.length <= lim) return t;
    const cut = t.slice(0, lim - 1);
    const sp = cut.lastIndexOf(" ");
    return (sp > Math.floor(lim * 0.45) ? cut.slice(0, sp) : cut) + "…";
  }

  function currentVerdict(){ return lastVerdict; }
  function ritualColor(r){
    return (r && SHELL.rituals.accents[r.accent]) || "#A99E90";
  }
  function ritualRgba(r, a){
    const c = hexToRgb(ritualColor(r));
    return "rgba(" + c.r + "," + c.g + "," + c.b + "," + a + ")";
  }
  function ritualLineText(v){
    const r = v ? ritualById(v.ritualId) : null;
    return r ? (r.title + " — " + r.flavor) : "";
  }
  function buildCurseText(v, withUrl){
    if(!v) return "";
    const lines = [v.name + " · " + v.powerLabel];
    if(v.situation) lines.push("«" + v.situation + "»");
    lines.push(v.punch, formatLift(v.lift));
    const rl = ritualLineText(v);
    if(rl) lines.push(rl);
    lines.push("", "ПРОКЛИНАТОР");
    if(withUrl && APP_URL) lines.push(APP_URL);
    // The satire line closes the caption so it is the last thing the recipient reads — never put anything after it.
    if(SHELL.share && SHELL.share.disclaimer) lines.push(SHELL.share.disclaimer);
    return lines.join("\n");
  }

  function paintPoster(v){
    const W = 1080, H = 1920;
    exportCanvas.width = W;
    exportCanvas.height = H;
    const ctx = exportCanvas.getContext("2d");
    const lastVerdict = v || currentVerdict();  // shadows the module state on purpose: history/share can paint any entry
    if(!ctx || !lastVerdict) return exportCanvas;

    const powerColor = powerColorOf(lastVerdict.powerId);
    const glow = lastVerdict.powerId === "anathema" ? 1.4 : lastVerdict.powerId === "whisper" ? 0.7 : 1;
    const ritualLine = ritualLineText(lastVerdict);
    const reserve = ritualLine ? 42 : 0;

    const bg = ctx.createLinearGradient(0, 0, 0, H);
    bg.addColorStop(0, "#110C0B");
    bg.addColorStop(0.45, "#0B0908");
    bg.addColorStop(1, "#070505");
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, W, H);
    const haze = ctx.createRadialGradient(W/2, H*0.22, 40, W/2, H*0.3, 760);
    haze.addColorStop(0, "rgba(140,14,24," + (0.26 * glow) + ")");
    haze.addColorStop(1, "rgba(11,9,8,0)");
    ctx.fillStyle = haze;
    ctx.fillRect(0, 0, W, H);
    addGrain(ctx, 0, 0, W, H, 5000);

    // Meta Stories/Reels safe zone: TOP ~14%, BOTTOM ~35%, SIDES ~6%.
    // contentSafeY = [0.14H, 0.65H] — everything that matters stays inside.
    const pad = Math.max(64, Math.floor(W * 0.06));
    const contentSafeTop = Math.floor(H * 0.14);
    const contentSafeBot = Math.floor(H * 0.65);
    const maxY = contentSafeBot;

    const innerPad = pad + 56;
    const textW = W - innerPad * 2;
    let y = contentSafeTop + 52;

    ctx.textAlign = "center";
    ctx.textBaseline = "top";

    // Brand
    drawCrown(ctx, W/2, y + 14, 46, "#C9A24A");
    y += 48;
    ctx.fillStyle = "rgba(237,228,214,.9)";
    ctx.font = "400 26px " + SERIF_CANVAS;
    setSpacing(ctx, 8);
    ctx.fillText("ПРОКЛИНАТОР", W/2, y);
    y += 36;
    ctx.fillStyle = "rgba(201,162,74,.85)";
    ctx.font = "400 15px " + SERIF_CANVAS;
    setSpacing(ctx, 6);
    ctx.fillText(String(DATA.tagline || "").toUpperCase(), W/2, y);
    setSpacing(ctx, 0);
    y += 46;

    const fullPunch = shortPunch(lastVerdict.punch, 320);
    const longPunch = String(fullPunch).length > 110;
    const hasSituation = !!lastVerdict.situation;

    // Sigil art — drop for long punches to keep everything in the safe band
    if(!longPunch){
      const r = Math.floor(W * 0.2);
      const artH = Math.floor(r * 0.42 * 2 + 40);
      const room = maxY - y;
      if(artH < room * 0.34){
        drawSigil(ctx, W/2, y + artH/2, r, powerColor, glow);
        y += artH + 14;
      }
    }

    // Sin
    ctx.fillStyle = "rgba(201,162,74,.75)";
    ctx.font = "600 15px " + SANS_CANVAS;
    setSpacing(ctx, 5);
    ctx.fillText(String(blocks[0] || "ГРЕХ").toUpperCase(), W/2, y);
    setSpacing(ctx, 0);
    y += 26;
    ctx.fillStyle = "rgba(237,228,214,.78)";
    ctx.font = "600 26px " + SANS_CANVAS;
    const sinLines = wrapText(ctx, String(lastVerdict.sin || ""), textW);
    for(let si=0; si<Math.min(sinLines.length, 2); si++){
      if(y + 32 > maxY) break;
      ctx.fillText(sinLines[si], W/2, y);
      y += 32;
    }
    y += 12;

    // Situation quote (≤2 lines)
    if(hasSituation){
      ctx.fillStyle = "rgba(237,228,214,.5)";
      ctx.font = "italic 400 24px " + SERIF_CANVAS;
      const qLines = wrapText(ctx, "«" + lastVerdict.situation + "»", textW);
      const qMax = Math.min(qLines.length, 2);
      for(let qi=0; qi<qMax; qi++){
        if(y + 30 > maxY - 200) break;
        let ln = qLines[qi];
        if(qi === qMax - 1 && qLines.length > qMax) ln = ln.replace(/[»]?$/, "…»");
        ctx.fillText(ln, W/2, y);
        y += 30;
      }
      y += 14;
    }

    // Punch (hero, serif)
    ctx.fillStyle = "#EDE4D6";
    let punchFont = 44, punchLH = 56;
    ctx.font = "400 " + punchFont + "px " + SERIF_CANVAS;
    let punchLines = wrapText(ctx, fullPunch, textW);
    if(punchLines.length > 5 || y + punchLines.length * punchLH > maxY - 170 - reserve){
      punchFont = 36; punchLH = 46;
      ctx.font = "400 " + punchFont + "px " + SERIF_CANVAS;
      punchLines = wrapText(ctx, fullPunch, textW);
    }
    if(punchLines.length > 6 || y + Math.min(punchLines.length, 7) * punchLH > maxY - 150 - reserve){
      punchFont = 30; punchLH = 38;
      ctx.font = "400 " + punchFont + "px " + SERIF_CANVAS;
      punchLines = wrapText(ctx, fullPunch, textW);
    }
    let maxPunchLines = 7;
    while(maxPunchLines > 3 && y + maxPunchLines * punchLH > maxY - 140 - reserve){
      maxPunchLines--;
    }
    for(let pi=0; pi<Math.min(punchLines.length, maxPunchLines); pi++){
      ctx.fillText(punchLines[pi], W/2, y);
      y += punchLH;
    }
    y += 18;

    // Lift — bone @.85 for AA contrast on soot
    ctx.fillStyle = "rgba(237,228,214,.85)";
    ctx.font = "500 24px " + SANS_CANVAS;
    const botLines = wrapText(ctx, formatLift(lastVerdict.lift), textW);
    for(let bi=0; bi<Math.min(botLines.length, 2); bi++){
      if(y + 30 > maxY) break;
      ctx.fillText(botLines[bi], W/2, y);
      y += 30;
    }

    // Catalog ritual flavor (accent-colored italic, ≤2 lines, stays in the safe band)
    if(ritualLine){
      y += 8;
      ctx.fillStyle = ritualRgba(ritualById(lastVerdict.ritualId), 0.9);
      ctx.font = "italic 400 22px " + SERIF_CANVAS;
      const rLines = wrapText(ctx, ritualLine, textW);
      for(let ri=0; ri<Math.min(rLines.length, 2); ri++){
        if(y + 28 > maxY) break;
        ctx.fillText(rLines[ri], W/2, y);
        y += 28;
      }
    }
    y += 22;

    // Name + power tag
    ctx.fillStyle = "#EDE4D6";
    ctx.font = "600 40px " + SERIF_CANVAS;
    const nameLines = wrapText(ctx, String(lastVerdict.name || ""), textW);
    for(let ni=0; ni<Math.min(nameLines.length, 2); ni++){
      if(y + 50 > maxY + 8) break;
      ctx.fillText(nameLines[ni], W/2, y);
      y += 50;
    }
    y += 6;
    if(y + 28 <= maxY + 12){
      ctx.fillStyle = powerColor;
      ctx.font = "700 20px " + SANS_CANVAS;
      setSpacing(ctx, 5);
      ctx.fillText(String(lastVerdict.powerLabel || "").toUpperCase(), W/2, y);
      setSpacing(ctx, 0);
      y += 30;
      ctx.strokeStyle = powerColor;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(W/2 - 56, y);
      ctx.lineTo(W/2 + 56, y);
      ctx.stroke();
    }

    // Ornamental frame hugs the content (blood outer, gold hairline inner); never leaves the safe band
    const frameBot = Math.min(contentSafeBot, Math.max(y + 64, contentSafeTop + Math.floor(H * 0.34)));
    ctx.save();
    ctx.strokeStyle = "rgba(179,18,31,.75)";
    ctx.lineWidth = 3;
    drawRoundedRect(ctx, pad, contentSafeTop, W - pad * 2, frameBot - contentSafeTop, 44);
    ctx.stroke();
    ctx.strokeStyle = "rgba(201,162,74,.28)";
    ctx.lineWidth = 1.5;
    drawRoundedRect(ctx, pad + 14, contentSafeTop + 14, W - pad * 2 - 28, frameBot - contentSafeTop - 28, 34);
    ctx.stroke();
    ctx.restore();

    // Footer may sit in the platform-chrome zone (non-critical)
    ctx.fillStyle = "rgba(201,162,74,.45)";
    ctx.font = "400 18px " + SERIF_CANVAS;
    setSpacing(ctx, 6);
    ctx.fillText(String(DATA.footer || "").toUpperCase(), W/2, H - Math.floor(H * 0.1));
    setSpacing(ctx, 0);
    if(APP_HOST){
      ctx.fillStyle = "rgba(237,228,214,.3)";
      ctx.font = "500 20px " + SANS_CANVAS;
      ctx.fillText(APP_HOST, W/2, H - Math.floor(H * 0.07));
    }

    return exportCanvas;
  }

  // Landscape OG card 1200×630 — downloadable companion; static Pages og:image is hero-altar.jpg
  function paintOgCard(v){
    const W = 1200, H = 630;
    if(!ogCanvas){
      ogCanvas = document.createElement("canvas");
      ogCanvas.setAttribute("aria-hidden", "true");
    }
    ogCanvas.width = W;
    ogCanvas.height = H;
    const ctx = ogCanvas.getContext("2d");
    const lastVerdict = v || currentVerdict();
    if(!ctx || !lastVerdict) return ogCanvas;

    const powerColor = powerColorOf(lastVerdict.powerId);
    ctx.fillStyle = "#0B0908";
    ctx.fillRect(0, 0, W, H);
    const g = ctx.createRadialGradient(W*0.5, H*0.3, 40, W*0.5, H*0.5, 560);
    g.addColorStop(0, "rgba(140,14,24,.28)");
    g.addColorStop(1, "rgba(11,9,8,0)");
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, H);
    addGrain(ctx, 0, 0, W, H, 2200);
    ctx.strokeStyle = "rgba(179,18,31,.7)";
    ctx.lineWidth = 2.5;
    drawRoundedRect(ctx, 28, 28, W - 56, H - 56, 28);
    ctx.stroke();

    const padX = 84;
    ctx.textAlign = "center";
    ctx.textBaseline = "top";

    drawCrown(ctx, W/2, 64, 36, "#C9A24A");
    ctx.fillStyle = "rgba(237,228,214,.7)";
    ctx.font = "400 20px " + SERIF_CANVAS;
    setSpacing(ctx, 6);
    ctx.fillText("ПРОКЛИНАТОР", W/2, 98);
    setSpacing(ctx, 0);

    let y = 150;
    ctx.fillStyle = "rgba(201,162,74,.8)";
    ctx.font = "600 20px " + SANS_CANVAS;
    ctx.fillText(String(lastVerdict.sin || ""), W/2, y);
    y += 40;

    ctx.fillStyle = "#EDE4D6";
    ctx.font = "400 40px " + SERIF_CANVAS;
    const punch = shortPunch(lastVerdict.punch, 160);
    const punchLines = wrapText(ctx, punch, W - padX * 2);
    for(let pi=0; pi<Math.min(punchLines.length, 3); pi++){
      ctx.fillText(punchLines[pi], W/2, y);
      y += 50;
    }
    y += 18;

    ctx.fillStyle = "rgba(237,228,214,.85)";
    ctx.font = "600 28px " + SERIF_CANVAS;
    ctx.fillText(String(lastVerdict.name || ""), W/2, y);
    y += 40;
    ctx.fillStyle = powerColor;
    ctx.font = "700 16px " + SANS_CANVAS;
    setSpacing(ctx, 4);
    ctx.fillText(String(lastVerdict.powerLabel || "").toUpperCase(), W/2, y);
    setSpacing(ctx, 0);

    ctx.fillStyle = "rgba(201,162,74,.5)";
    ctx.font = "400 16px " + SERIF_CANVAS;
    setSpacing(ctx, 5);
    ctx.fillText(String(DATA.footer || "").toUpperCase(), W/2, H - 70);
    setSpacing(ctx, 0);

    return ogCanvas;
  }

  async function prefetchShareBlob(){
    shareBlob = null;
    ogBlob = null;
    if(!lastVerdict) return;
    try{
      await waitFonts(800);
      paintPoster();
      shareBlob = await new Promise(function(res){ exportCanvas.toBlob(res, "image/png"); });
      paintOgCard();
      ogBlob = await new Promise(function(res){ ogCanvas.toBlob(res, "image/png"); });
    }catch(e){ shareBlob = null; ogBlob = null; }
  }

  function downloadBlob(blob, filename){
    if(!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename || "proklinator";
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function(){ URL.revokeObjectURL(url); }, 1500);
  }
  function legacyCopy(text){
    try{
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand("copy");
      ta.remove();
      return !!ok;
    }catch(e){ return false; }
  }
  // Clipboard API first, execCommand second. opts.silent: caller owns the toast.
  async function copyText(text, opts){
    let ok = false;
    try{
      if(navigator.clipboard && navigator.clipboard.writeText){
        await navigator.clipboard.writeText(text);
        ok = true;
      }
    }catch(e){}
    if(!ok) ok = legacyCopy(text);
    if(ok && !(opts && opts.silent)) showToast(DATA.toastCopy);
    return ok;
  }
  function posterName(v){ return "proklinator-" + ((v && v.sinId) || "card") + ".png"; }
  async function posterBlob(v){
    await waitFonts(800);
    paintPoster(v);
    return new Promise(function(res){ exportCanvas.toBlob(res, "image/png"); });
  }

  // Shares the current result by default; history rows pass their own entry.
  // 1) Share File: Web Share with the PNG attached (text-only sheet where files can't be shared).
  // 2) Fallback (no Web Share, or it failed for a reason other than the user dismissing it): save the PNG + copy the caption,
  //    and the toast states exactly what happened. The blob is reused for the download so the export canvas can never be stale.
  async function shareCard(v){
    v = v || lastVerdict;
    if(!v) return;
    const isCurrent = v === lastVerdict;
    const shareText = buildCurseText(v, true);
    let blob = isCurrent ? shareBlob : null;
    if(!blob){ try{ blob = await posterBlob(v); }catch(e){ blob = null; } }
    if(navigator.share){
      try{
        const file = blob ? new File([blob], "proklinator.png", { type: "image/png" }) : null;
        // No separate `url`: share sheets append it after `text`, which would push the satire line off the end
        // (and duplicate the link). The caption already carries APP_URL right above «Шутка / розыгрыш. Не угроза.».
        const data = { title: "ПРОКЛИНАТОР", text: shareText };
        if(file && navigator.canShare && navigator.canShare({ files: [file] })) data.files = [file];
        await navigator.share(data);
        showToast(DATA.toastShare);
        countShare();
        return;
      }catch(e){
        if(e && e.name === "AbortError") return;   // sheet dismissed — nothing went out, no toast, no count
      }
    }
    if(!blob){ try{ blob = await posterBlob(v); }catch(e){ blob = null; } }
    const saved = !!blob;
    if(saved) downloadBlob(blob, posterName(v));
    const copied = await copyText(shareText, { silent: true });
    const S = SHELL.share;
    showToast(saved ? (copied ? S.savedCopied : S.saved) : (copied ? DATA.toastCopy : S.failed));
    if(saved || copied) countShare();
  }
  // Counted only when a share actually went out (share sheet resolved or the PNG fallback was handed over).
  function countShare(){
    stats.shares = (stats.shares | 0) + 1;
    saveStats();
    checkBadges();
  }

  /* ---------- result ---------- */
  function typewriterPunch(el, text, opts){
    opts = opts || {};
    if(typewriterTimer){ clearTimeout(typewriterTimer); typewriterTimer = 0; }
    text = String(text || "");
    if(!el) return;
    if(reduced || !text.length){
      el.textContent = text;
      return;
    }
    el.textContent = "";
    const n = text.length;
    const total = Math.min(1200, Math.max(180, Math.floor(n * 16)));
    const per = Math.max(8, Math.floor(total / n));
    let i = 0;
    const haptic = !!opts.haptic;
    function step(){
      i++;
      el.textContent = text.slice(0, i);
      if(haptic && i % 5 === 0) vibe(8);
      if(i < n){
        typewriterTimer = setTimeout(step, per);
      } else {
        typewriterTimer = 0;
        el.textContent = text;
      }
    }
    step();
  }

  function renderRitualLine(v){
    const box = $("vRitualLine");
    const r = v ? ritualById(v.ritualId) : null;
    if(!r){ box.hidden = true; return; }
    box.hidden = false;
    const ico = $("vRitualIco");
    ico.innerHTML = ritualIcon(r);
    ico.style.color = ritualColor(r);
    $("vRitualName").textContent = r.title + ".";
    $("vRitualFlavor").textContent = r.flavor;
  }
  function syncFavBtn(){
    const b = $("favBtn");
    const entry = (lastVerdict && lastVerdict.hid) ? historyFind(lastVerdict.hid) : null;
    const on = !!(entry && entry.fav);
    b.classList.toggle("on", on);
    b.setAttribute("aria-pressed", on ? "true" : "false");
    b.querySelector("span").textContent = on ? SHELL.result.favOn : SHELL.result.fav;
  }
  function syncHarderBtn(){
    const atMax = !!(lastVerdict && lastVerdict.powerId === "anathema");
    $("harderText").textContent = atMax ? SHELL.result.harderMax : SHELL.result.harder;
  }

  function showResult(opts){
    opts = opts || {};
    hardCloseOverlay();
    castScreen.classList.add("hidden");
    result.classList.remove("hidden");
    result.classList.add("show");
    document.body.classList.add("is-result");
    if(lastVerdict.fresh){
      lastVerdict.fresh = false;
      recordRitual(lastVerdict);
    }
    $("vName").textContent = lastVerdict.name;
    $("vPower").textContent = lastVerdict.powerLabel;
    $("vPower").dataset.power = lastVerdict.powerId || "";
    $("vSin").textContent = lastVerdict.sin;
    renderRitualLine(lastVerdict);
    syncFavBtn();
    syncHarderBtn();

    const sitEl = $("vSituation");
    if(lastVerdict.situation){
      sitEl.hidden = false;
      sitEl.textContent = "«" + lastVerdict.situation + "»";
    } else {
      sitEl.hidden = true;
      sitEl.textContent = "";
    }

    const setup = (lastVerdict.setup || "").trim();
    const squash = function(s){ return String(s || "").toLowerCase().replace(/[«»"'.,!?…\s]+/g, " ").trim(); };
    const setupDup = !setup || squash(setup) === squash(lastVerdict.sin);
    if(setup && !setupDup){
      $("vSetup").hidden = false;
      $("vSetup").textContent = setup;
    } else {
      $("vSetup").hidden = true;
      $("vSetup").textContent = "";
    }
    $("lblLift").textContent = formatLiftLabel(lastVerdict.lift);
    $("vLift").textContent = formatLift(lastVerdict.lift);

    const stampSvg = $("stampMark").querySelector("svg");
    if(stampSvg){
      const sc = powerColorOf(lastVerdict.powerId);
      stampSvg.querySelectorAll(".ring-s").forEach(function(el){ el.setAttribute("stroke", sc); });
    }

    result.classList.remove("flash-anathema");
    const flash = $("redFlash");
    if(flash){ flash.classList.remove("on"); void flash.offsetWidth; }

    const punchEl = $("vPunch");
    const hard = lastVerdict.powerId === "anathema";
    punchEl.style.opacity = "1";
    punchEl.style.transform = "none";

    const stamp = $("stampMark");
    const nameEl = $("vName");
    if(!reduced && hasAnime){
      stamp.style.opacity = "0"; stamp.style.transform = "scale(2.6) rotate(-14deg)";
      nameEl.style.opacity = "0"; nameEl.style.transform = "translateY(8px)";

      if(hard && flash){
        flash.classList.add("on");
        result.classList.add("flash-anathema");
      }

      anime.timeline({ easing: "easeOutExpo" })
        .add({ targets: nameEl, opacity: [0, 1], translateY: [10, 0], duration: 380 })
        .add({
          targets: stamp,
          opacity: [0, 1],
          scale: hard ? [3.2, 1] : [2.4, 1],
          rotate: hard ? [-18, 0] : [-12, 0],
          duration: hard ? 520 : 420,
          easing: hard ? "easeOutElastic(1, .55)" : "easeOutBack(1.4)"
        }, "-=120");

      if(hard){
        anime({
          targets: result,
          translateX: [
            { value: -10, duration: 40 },
            { value: 12, duration: 50 },
            { value: -8, duration: 45 },
            { value: 6, duration: 40 },
            { value: 0, duration: 60 }
          ],
          easing: "easeInOutSine"
        });
      }
      setTimeout(function(){
        typewriterPunch(punchEl, lastVerdict.punch, { haptic: hard });
      }, hard ? 280 : 180);
    } else {
      stamp.style.opacity = "1"; stamp.style.transform = "none";
      nameEl.style.opacity = "1"; nameEl.style.transform = "none";
      typewriterPunch(punchEl, lastVerdict.punch, { haptic: false });
    }

    prefetchShareBlob();
    if(!opts.silent) showToast(DATA.toastOk);
    try{ window.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" }); }catch(e){ window.scrollTo(0, 0); }
  }

  function runRitual(name, situation, opts){
    opts = opts || {};
    const catId = opts.catId !== undefined ? opts.catId : categoryId;
    const ritId = opts.ritualId !== undefined ? opts.ritualId : ritualId;
    const ritual = ritualById(ritId);
    casting = true;
    cast.disabled = true;
    cast.classList.add("busy");
    castText.textContent = DATA.busy;

    const fx = Object.assign({
      spin: 1, glow: 0.7, particles: 56, shake: 6,
      duration: 3200, rings: 4, vibrate: 0, color: "#B3121F"
    }, fxTable[powerId] || fxTable.seal || {});

    const gender = inferGender(name, situation);
    const matchedSin = situation ? matchSin(situation, name, noMat, catId) : null;
    const picked = pickVerdict({
      sin: matchedSin, gender: gender, powerId: powerId, clean: noMat,
      pool: catId ? sinsForCategory(catId) : null
    });
    const verd = picked.verd;
    const sin = picked.sin;
    const catAuto = catId ? null : inferCategory(situation, sin);   // stats only; never restricts a reroll
    const power = powers.find(function(p){ return p.id === powerId; }) || powers[1];
    let setup = verd.setup ? conjugate(fillName(verd.setup, name), gender) : "";
    const punch = conjugate(fillName(picked.punchRaw, name), gender);
    let lift = conjugate(fillName(verd.lift, name), gender);
    if(noMat){
      if(isVulgar(lift)) lift = CLEAN_STUB_LIFT;
      if(isVulgar(setup)) setup = "";
    }

    lastVerdict = {
      name: name,
      situation: situation,
      gender: gender,
      sin: picked.sinName || sin.name,
      sinId: sin.id,
      category: sin.category,
      sinObj: sin,
      setup: setup,
      punch: punch,
      lift: lift,
      powerId: powerId,
      powerLabel: power.label,
      usedPower: picked.usedPower,
      stub: !!picked.stub,
      clean: noMat,
      matched: !!matchedSin,
      verdId: verd.id,
      catId: catId || null,
      catAuto: catAuto || null,
      ritualId: ritual ? ritual.id : null,
      ts: Date.now(),
      hid: null,
      fresh: true
    };

    let chants = (ritualByPower[powerId] || DATA.ritual || []).slice();
    if(!chants.length) chants = DATA.ritual || ["Готово."];
    if(ritual && ritual.flavor) chants.splice(Math.min(4, Math.max(0, chants.length - 1)), 0, ritual.flavor);

    openOverlay(fx);

    const duration = reduced ? 400 : Math.max(1200, fx.duration | 0);
    const step = duration / Math.max(1, chants.length);
    progress.style.width = "0%";
    chant.textContent = fillChant(chants[0], name, gender);

    function finish(){
      casting = false;
      if(threeState && threeState.orb){
        threeState.orb.userData.scaleBoost = 1.35;
        threeState.shake = fx.shake;
      }
      setTimeout(function(){ showResult(); }, reduced ? 60 : 220);
    }

    if(reduced){
      overlay.style.opacity = "1";
      progress.style.width = "100%";
      chant.textContent = fillChant(chants[chants.length - 1], name, gender);
      setTimeout(finish, 320);
      return;
    }

    if(hasAnime){
      const prog = { w: 0 };
      const chantIdx = { i: 0 };
      const tl = anime.timeline({ easing: "easeOutQuad", complete: finish });
      ritualTimeline = tl;
      tl.add({ targets: overlay, opacity: [0, 1], duration: 280 })
        .add({
          targets: prog, w: 100, duration: duration, easing: "linear",
          update: function(){ progress.style.width = prog.w + "%"; }
        }, 0)
        .add({
          targets: chantIdx, i: chants.length - 1, duration: duration, easing: "linear", round: 1,
          update: function(){
            const idx = Math.min(chants.length - 1, chantIdx.i | 0);
            chant.textContent = fillChant(chants[idx], name, gender);
          }
        }, 0);

      if(threeState && threeState.orb){
        tl.add({
          targets: threeState.orb.scale,
          x: [0.7, 1], y: [0.7, 1], z: [0.7, 1],
          duration: 600,
          easing: "easeOutElastic(1, .6)"
        }, 0);
        anime({
          targets: threeState.orb.userData,
          scaleBoost: [1, 1.08, 1],
          duration: Math.min(1200, duration / 2),
          loop: Math.max(1, Math.floor(duration / 1200)),
          easing: "easeInOutSine"
        });
        if(powerId === "anathema" || fx.shake > 8){
          anime({
            targets: threeState,
            shake: [fx.shake, fx.shake * 0.4, fx.shake],
            duration: duration,
            easing: "easeInOutSine"
          });
        }
      } else {
        tl.add({
          targets: sealStage,
          scale: [0.86, 1.05, 0.96],
          opacity: [0.7, 1],
          duration: Math.min(900, duration * 0.4),
          easing: "easeOutQuad"
        }, 0);
      }

      tl.add({ targets: progress, opacity: [1, 0.4, 1], duration: 280, easing: "easeInOutQuad" });
    } else {
      if(!reduced){
        overlay.animate([{ opacity: 0 }, { opacity: 1 }], { duration: 220, easing: "ease-out", fill: "forwards" });
      } else {
        overlay.style.opacity = "1";
      }
      let i = 0;
      function next(){
        i++;
        const pct = Math.min(100, (i / chants.length) * 100);
        progress.style.width = pct + "%";
        if(i >= chants.length){
          chant.textContent = fillChant(chants[chants.length - 1], name, gender);
          setTimeout(finish, 280);
          return;
        }
        chant.textContent = fillChant(chants[i], name, gender);
        setTimeout(next, step);
      }
      setTimeout(next, step);
    }
  }

  function readForm(){
    return {
      name: cleanStr(who.value, WHO_MAX),
      situation: cleanStr(what.value, WHAT_MAX)
    };
  }

  cast.addEventListener("click", function(){
    if(casting) return;
    const f = readForm();
    if(!f.name){ failEmpty(); return; }
    emptyHint.classList.remove("show");
    runRitual(f.name, f.situation);
  });

  who.addEventListener("keydown", function(e){
    if(e.key === "Enter"){
      e.preventDefault();
      if((what.value || "").trim()) cast.click();
      else { try{ what.focus(); }catch(err){} }
    }
  });
  what.addEventListener("keydown", function(e){
    if(e.key === "Enter" && (e.metaKey || e.ctrlKey)){ e.preventDefault(); cast.click(); }
  });

  function backToForm(){
    hardCloseOverlay();
    shareBlob = null;
    if(typewriterTimer){ clearTimeout(typewriterTimer); typewriterTimer = 0; }
    result.classList.remove("show");
    result.classList.remove("flash-anathema");
    result.classList.add("hidden");
    castScreen.classList.remove("hidden");
    document.body.classList.remove("is-result");
    cast.disabled = false;
    cast.classList.remove("busy");
    castText.textContent = DATA.cta;
  }

  $("resetBtn").addEventListener("click", function(){
    if(casting) return;
    const wasResult = document.body.classList.contains("is-result");
    backToForm();
    if(!wasResult){
      who.value = "";
      what.value = "";
      updateWho();
      updateWhat();
      emptyHint.classList.remove("show");
    }
    vibe(VIBE.light);
    try{ window.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" }); }catch(e){ window.scrollTo(0, 0); }
  });

  // «Сохранить картинку» never touches Web Share: prefetched blob when ready, otherwise a fresh paint.
  $("saveBtn").addEventListener("click", async function(){
    if(!lastVerdict) return;
    let blob = shareBlob;
    if(!blob){ try{ blob = await posterBlob(lastVerdict); }catch(e){ blob = null; } }
    if(!blob){ showToast(SHELL.share.failed); return; }
    downloadBlob(blob, posterName(lastVerdict));
    showToast(SHELL.share.saved);
  });
  $("shareBtn").addEventListener("click", function(){ shareCard(); });
  $("copyCurseBtn").addEventListener("click", async function(){
    if(!lastVerdict) return;
    const ok = await copyText(buildCurseText(lastVerdict, true));
    if(!ok) showToast(SHELL.share.copyFailed);
  });
  // Reroll inputs: a result opened from history keeps its own who/what; a fresh one prefers the live form.
  function rerollInputs(){
    const f = readForm();
    const fromHist = !!(lastVerdict && lastVerdict.fromHistory);
    const name = fromHist ? (lastVerdict.name || f.name) : (f.name || (lastVerdict && lastVerdict.name) || "");
    const situation = fromHist ? (lastVerdict.situation || "") : (f.situation || (lastVerdict && lastVerdict.situation) || "");
    return { name: name, situation: situation };
  }
  function prepareReroll(){
    // Same who/what — new verdict only; the overlay covers the stale card until showResult refills it
    hardCloseOverlay();
    shareBlob = null;
    if(typewriterTimer){ clearTimeout(typewriterTimer); typewriterTimer = 0; }
    result.classList.remove("flash-anathema");
    document.body.classList.remove("is-result");
  }
  $("againBtn").addEventListener("click", function(){
    if(casting) return;
    const f = rerollInputs();
    if(!f.name){
      backToForm();
      try{ who.focus(); }catch(e){}
      return;
    }
    prepareReroll();
    vibe(VIBE.whisper);
    runRitual(f.name, f.situation, {
      catId: lastVerdict ? lastVerdict.catId : categoryId,
      ritualId: lastVerdict ? lastVerdict.ritualId : ritualId
    });
  });

  const POWER_ORDER = ["whisper", "seal", "anathema"];
  function nextPower(pid){
    const i = POWER_ORDER.indexOf(pid);
    return POWER_ORDER[Math.min(POWER_ORDER.length - 1, i < 0 ? 1 : i + 1)];
  }
  // «Ещё жёстче»: bump the power one step (sticks on the form too) and reroll the same case
  $("harderBtn").addEventListener("click", function(){
    if(casting || !lastVerdict) return;
    const f = rerollInputs();
    if(!f.name){ backToForm(); return; }
    const np = nextPower(lastVerdict.powerId);
    const bumped = np !== lastVerdict.powerId;
    powerId = np;
    syncPowerUI();
    savePrefs();
    prepareReroll();
    if(bumped) showToast(SHELL.result.harderToast);
    vibe(VIBE.seal);
    runRitual(f.name, f.situation, { catId: lastVerdict.catId, ritualId: lastVerdict.ritualId });
  });

  $("favBtn").addEventListener("click", function(){
    if(!lastVerdict) return;
    let entry = lastVerdict.hid ? historyFind(lastVerdict.hid) : null;
    if(!entry){
      // Deleted from history while still on screen → resurrect it as a favorite
      entry = entryFromVerdict(lastVerdict);
      lastVerdict.hid = entry.id;
      historyPush(entry);
    }
    entry.fav = !entry.fav;
    saveHistory();
    syncFavBtn();
    vibe(VIBE.light);
    showToast(entry.fav ? SHELL.history.favOn : SHELL.history.favOff);
    checkBadges();
  });

  $("newBtn").addEventListener("click", function(){
    if(casting) return;
    backToForm();
    vibe(VIBE.light);
    try{ window.scrollTo({ top: 0, behavior: reduced ? "auto" : "smooth" }); }catch(e){ window.scrollTo(0, 0); }
  });

  document.addEventListener("visibilitychange", function(){
    if(document.hidden && !casting){
      stopAsh();
    }
  });

