    $("proBannerTitle").textContent = SHELL.profile.proBanner.title;
    $("proBannerSub").textContent = SHELL.profile.proBanner.sub;
    $("proBannerCta").textContent = SHELL.profile.proBanner.cta;

    const menu = $("profMenu");
    menu.innerHTML = "";
    SHELL.profile.menu.forEach(function(m){
      let val = "", gold = false, label = m.label;
      if(m.id === "badges") val = profile.badges.length + "/" + SHELL.badges.items.length;
      else if(m.id === "stats") val = String(stats.total | 0);
      else if(m.id === "leaderboard") val = "#" + userRank("all");
      else if(m.id === "premium"){ if(profile.pro){ label = m.labelPro; val = SHELL.rituals.locked; gold = true; } }
      menu.appendChild(menuItem(m.id, label, val, gold));
    });
    $("profDocsLabel").textContent = SHELL.profile.docsLabel;
    const docs = $("profDocsMenu");
    docs.innerHTML = "";
    SHELL.profile.docs.forEach(function(m){ docs.appendChild(menuItem(m.id, m.label, "", false)); });
    $("nickForm").classList.remove("on");
    renderAvatar();
    closeAvatarPicker();
    renderA2hsRow();
