  /* ---------- stats ---------- */
  const WEEKDAYS = ["вс","пн","вт","ср","чт","пт","сб"];
  function renderStats(){
    $("statsTitle").textContent = SHELL.stats.title;
    const body = $("statsBody");
    body.innerHTML = "";
    const pct = worsePct();

    const hero = document.createElement("div");
    hero.className = "card stat-hero";
    hero.innerHTML = '<div class="eyebrow"></div><div class="big"><b></b></div><p class="sentence"></p><div class="bars"></div><div class="bars-labels"></div><div class="bars-cap"></div>';
    hero.querySelector(".eyebrow").textContent = SHELL.profile.counters[1] + " · " + fmtK(karmaAll());
    hero.querySelector(".big b").textContent = pct + "%";
    hero.querySelector(".sentence").textContent = fmt(SHELL.stats.worldWorse, { x: pct });
    const bars = hero.querySelector(".bars"), labels = hero.querySelector(".bars-labels");
    const days = [];
    for(let i=6;i>=0;i--){ const d = new Date(); d.setDate(d.getDate() - i); days.push(d); }
    let max = 0;
    days.forEach(function(d){ max = Math.max(max, stats.byDay[dayKey(d)] || 0); });
    days.forEach(function(d){
      const n = stats.byDay[dayKey(d)] || 0;
      const i = document.createElement("i");
      i.style.height = (max ? Math.max(4, Math.round(n / max * 100)) : 4) + "%";
      if(!n) i.classList.add("zero");
      i.title = n + "";
      bars.appendChild(i);
      const l = document.createElement("span");
      l.textContent = WEEKDAYS[d.getDay()];
      labels.appendChild(l);
    });
    hero.querySelector(".bars-cap").textContent = SHELL.stats.chartLabel;
    body.appendChild(hero);

    const cards = document.createElement("div");
    cards.className = "stat-cards";
    const cleanPct = stats.total ? Math.round((stats.clean | 0) / stats.total * 100) + "%" : "0%";
    [[stats.total | 0, SHELL.stats.cards[0]], [stats.byPower.anathema | 0, SHELL.stats.cards[1]], [cleanPct, SHELL.stats.cards[2]], [favCount(), SHELL.stats.cards[3]]].forEach(function(c){
      const d = document.createElement("div");
      d.className = "card stat-card";
      d.innerHTML = "<b></b><small></small>";
      d.querySelector("b").textContent = c[0];
      d.querySelector("small").textContent = c[1];
      cards.appendChild(d);
    });
    body.appendChild(cards);

    const pw = document.createElement("div");
    pw.className = "card pbars";
    pw.innerHTML = '<div class="group-label"></div>';
    pw.querySelector(".group-label").textContent = SHELL.stats.byPower;
    const totalP = Math.max(1, stats.total | 0);
    powers.forEach(function(p){
      const n = stats.byPower[p.id] | 0;
      const row = document.createElement("div");
      row.className = "pbar";
      row.style.setProperty("--bar", powerColorOf(p.id));
      row.innerHTML = "<span></span><div class=\"track\"><i></i></div><em></em>";
      row.querySelector("span").textContent = p.label;
      row.querySelector("i").style.width = Math.round(n / totalP * 100) + "%";
      row.querySelector("em").textContent = n;
      pw.appendChild(row);
    });
    body.appendChild(pw);

    const catKeys = Object.keys(stats.byCategory).filter(function(k){ return stats.byCategory[k] > 0; })
      .sort(function(a, b){ return stats.byCategory[b] - stats.byCategory[a]; }).slice(0, 5);
    if(catKeys.length){
      const pc = document.createElement("div");
      pc.className = "card pbars";
      pc.innerHTML = '<div class="group-label"></div>';
      pc.querySelector(".group-label").textContent = SHELL.stats.byCategory;
      catKeys.forEach(function(k){
        const n = stats.byCategory[k] | 0;
        const c = catById(k);
        const row = document.createElement("div");
        row.className = "pbar";
        row.style.setProperty("--bar", "var(--bone-dim)");
        row.innerHTML = "<span></span><div class=\"track\"><i></i></div><em></em>";
        row.querySelector("span").textContent = c ? c.title : SHELL.stats.noCategory;
        row.querySelector("i").style.width = Math.round(n / totalP * 100) + "%";
        row.querySelector("em").textContent = n;
        pc.appendChild(row);
      });
      body.appendChild(pc);
    }
  }

  /* ---------- leaderboard ---------- */
  let lbPeriod = "all";
  function renderLeaderboard(){
    $("lbTitle").textContent = SHELL.leaderboard.title;
    $("lbSub").textContent = SHELL.leaderboard.subtitle;
    renderSeg($("lbSeg"), SHELL.leaderboard.tabs, ["week", "month", "all"], lbPeriod, function(v){ lbPeriod = v; renderLeaderboard(); });
    $("lbHead").textContent = SHELL.leaderboard.metric;
    const scale = SHELL.leaderboard.periodScale[lbPeriod] || 1;
    const mine = lbPeriod === "all" ? karmaAll() : karmaSince(Date.now() - (lbPeriod === "week" ? 7 : 30) * 864e5);
    const rows = SHELL.leaderboard.seeds.map(function(s){ return { name: s.nick, karma: Math.round(s.karma * scale), me: false }; });
    rows.push({ name: displayNick(), karma: mine, me: true });
    // PRO bullet 5 — «Приоритет в локальной таблице кармы»: a legend wins ties, a mortal loses them.
    const meFirst = profile.pro ? -1 : 1;
    rows.sort(function(a, b){ return (b.karma - a.karma) || (a.me ? meFirst : b.me ? -meFirst : 0); });
    const list = $("lbList");
    list.innerHTML = "";
    rows.forEach(function(r, i){
      const row = document.createElement("div");
      row.className = "lb-row" + (r.me ? " me" : "") + (i < 3 ? " top" : "") + (i === 0 ? " top1" : "");
      row.innerHTML = '<span class="rank"></span><span class="av" aria-hidden="true"></span><span class="nm"><span></span></span><span class="kv"></span>';
      row.querySelector(".rank").textContent = i + 1;
      row.querySelector(".av").textContent = (r.name || "?").trim().charAt(0).toUpperCase();
      row.querySelector(".nm > span").textContent = r.name;
      if(r.me){
        if(profile.pro) row.querySelector(".nm").insertAdjacentHTML("beforeend", ICO.crownGold);
        const you = document.createElement("span");
        you.className = "you";
        you.textContent = "(" + SHELL.leaderboard.you + ")";
        row.querySelector(".nm").appendChild(you);
        row.setAttribute("aria-current", "true");
      }
      row.querySelector(".kv").textContent = fmtK(r.karma);
      list.appendChild(row);
    });
  }

